// Plausible Analytics template: App + Postgres + ClickHouse. Runs in the panel's template sandbox; see templates/README.md.

import { env, PRIMARY_DOMAIN, randomBase64, ref } from "~templates-utils";

interface Input {
  serviceName: string;
  image: string;
  clickhouseImage: string;
}

export function generate(input: Input) {
  const db = `${input.serviceName}-db`;
  const events = `${input.serviceName}-events`;
  return {
    services: [
      { type: "postgres", data: { serviceName: db, version: "16", database: "plausible" } },
      {
        type: "app",
        data: {
          serviceName: events,
          source: { type: "image", image: input.clickhouseImage },
          env: env({ CLICKHOUSE_SKIP_USER_SETUP: "1" }),
          ports: [8123],
          mounts: [{ type: "volume", name: "data", mountPath: "/var/lib/clickhouse" }],
        },
      },
      {
        type: "app",
        data: {
          serviceName: input.serviceName,
          source: { type: "image", image: input.image },
          env: env({
            BASE_URL: ref(input.serviceName, "URL"),
            SECRET_KEY_BASE: randomBase64(48),
            TOTP_VAULT_KEY: randomBase64(32),
            DATABASE_URL: ref(db, "INTERNAL_URL"),
            CLICKHOUSE_DATABASE_URL: `http://${events}:8123/plausible_events_db`,
          }),
          domains: [{ host: PRIMARY_DOMAIN, port: 8000 }],
          deploy: { command: "/entrypoint.sh db createdb && /entrypoint.sh db migrate && /entrypoint.sh run" },
        },
      },
    ],
  };
}

// Prometheus template: App. Runs in the panel's template sandbox; see templates/README.md.

import { PRIMARY_DOMAIN } from "~templates-utils";

interface Input {
  serviceName: string;
  image: string;
  retention?: string;
}

const config = `global:
  scrape_interval: 15s
scrape_configs:
  - job_name: prometheus
    static_configs:
      - targets: ["localhost:9090"]
`;

export function generate(input: Input) {
  const retention = /^[0-9]+[smhdwy]$/.test(input.retention ?? "") ? input.retention : "15d";
  return {
    services: [
      {
        type: "app",
        data: {
          serviceName: input.serviceName,
          source: { type: "image", image: input.image },
          domains: [{ host: PRIMARY_DOMAIN, port: 9090 }],
          mounts: [
            { type: "volume", name: "data", mountPath: "/prometheus" },
            { type: "file", content: config, mountPath: "/etc/prometheus/prometheus.yml" },
          ],
          deploy: {
            command: `exec /bin/prometheus --config.file=/etc/prometheus/prometheus.yml --storage.tsdb.path=/prometheus --storage.tsdb.retention.time=${retention}`,
          },
        },
      },
    ],
  };
}

// Redis Insight template: App + Redis. Runs in the panel's template sandbox; see templates/README.md.

import { PRIMARY_DOMAIN } from "~templates-utils";

interface Input {
  serviceName: string;
  image: string;
  withRedis?: boolean;
}

export function generate(input: Input) {
  const services: unknown[] = [];
  if (input.withRedis !== false) services.push({ type: "redis", data: { serviceName: `${input.serviceName}-redis`, version: "7.4" } });
  services.push({
    type: "app",
    data: {
      serviceName: input.serviceName,
      source: { type: "image", image: input.image },
      domains: [{ host: PRIMARY_DOMAIN, port: 5540 }],
      mounts: [{ type: "volume", name: "data", mountPath: "/data" }],
    },
  });
  return { services };
}

